const webhookItem = $input.first().json || {};
const headers = webhookItem.headers || {};
const expectedWebhookSecret = String($env.N8N_BUFFERED_WEBHOOK_SECRET || '').trim();
const receivedWebhookSecret = String(
  headers['x-autobots-webhook-secret'] ||
  headers['X-Autobots-Webhook-Secret'] ||
  ''
).trim();

if (!expectedWebhookSecret) {
  throw new Error('N8N_BUFFERED_WEBHOOK_SECRET is not configured');
}

if (receivedWebhookSecret !== expectedWebhookSecret) {
  throw new Error('Unauthorized webhook request');
}

// n8n Webhook Trigger wraps the real HTTP payload inside `body`.
// Manual tests or older exports may pass the payload directly, so support both shapes.
let input = webhookItem;
if (webhookItem.body !== undefined) {
  if (typeof webhookItem.body === 'string') {
    try {
      input = JSON.parse(webhookItem.body || '{}');
    } catch (error) {
      input = {};
    }
  } else if (webhookItem.body && typeof webhookItem.body === 'object') {
    input = webhookItem.body;
  }
}

const onlyDigits = (value) => String(value || '').replace(/\D+/g, '');

// Normal expected payload from the FastAPI message-buffer service.
let phone = onlyDigits(input.phone);
let messages = Array.isArray(input.messages) ? input.messages : [];
let rawText = input.combined_text || input.text || input.message || '';
let pushName = input.push_name || input.name || '';
let messageType = input.message_type || input.type || 'text';
let instance = input.instance || 'autobots-main';
let bufferId = input.buffer_id || '';
let receivedAt = input.received_at || new Date().toISOString();
let containsAudio = input.contains_audio === true || messageType === 'audio';

// Defensive fallback: if this node is accidentally called with an Evolution-style payload,
// extract the same normalized fields instead of returning empty data.
if ((!phone || !rawText) && input.data && typeof input.data === 'object') {
  const data = input.data;
  const key = data.key || {};
  const jid = key.remoteJidAlt || key.remoteJid || '';
  const message = data.message || {};

  phone = phone || onlyDigits(jid.split('@')[0]);
  pushName = pushName || data.pushName || '';
  instance = input.instance || data.instance || instance;
  messageType = data.messageType || messageType;
  rawText = rawText ||
    message.conversation ||
    message.extendedTextMessage?.text ||
    message.imageMessage?.caption ||
    message.videoMessage?.caption ||
    '';
  receivedAt = data.messageTimestamp
    ? new Date(Number(data.messageTimestamp) * 1000).toISOString()
    : receivedAt;
}

let combinedText = String(rawText || '').replace(/\s+/g, ' ').trim();

if (!combinedText && messages.length) {
  combinedText = messages
    .map((message) => message.text || message.body || message.transcription || '')
    .filter(Boolean)
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();
}

if (!combinedText && containsAudio) {
  combinedText = 'Recibí un audio, pero por ahora Nicolás va a revisarlo manualmente.';
}

return [{
  json: {
    source: input.source || 'message-buffer',
    instance,
    phone,
    push_name: pushName,
    message_type: messageType || (containsAudio ? 'audio' : 'text'),
    combined_text: combinedText,
    messages,
    message_count: Number(input.message_count || messages.length || (combinedText ? 1 : 0)),
    buffer_id: bufferId,
    received_at: receivedAt,
    contains_audio: containsAudio,
  },
}];

const original = $('Set / Normalize Input').item.json;
const response = $input.first().json || {};
let text = response.candidates?.[0]?.content?.parts?.[0]?.text
  || response.choices?.[0]?.message?.content
  || '{}';
text = String(text).replace(/```json/g, '').replace(/```/g, '').trim();

let parsed = {};
try {
  parsed = JSON.parse(text);
} catch (error) {
  parsed = {};
}

const rawMessage = String(original.combined_text || '');
const message = rawMessage.toLowerCase();

function clean(value) {
  const text = String(value || '').trim();
  return text || null;
}

function normalizeIntent(value) {
  const raw = String(value || 'unknown').toLowerCase().replace(/[\s-]/g, '_');
  const aliases = {
    wantsmeeting: 'wants_meeting', meeting: 'wants_meeting', reunion: 'wants_meeting', reunión: 'wants_meeting',
    wantsdemo: 'wants_demo', demo: 'wants_demo',
    wantscallback: 'wants_callback', callback: 'wants_callback', llamada: 'wants_callback',
    price: 'wants_price', precio: 'wants_price',
  };
  return aliases[raw] || raw;
}

function inferBusinessType(msg) {
  const checks = [
    ['inmobiliaria', /inmobiliaria|propiedad|departamento|alquiler|venta de casas|bienes ra[ií]ces/],
    ['peluquería', /peluquer|sal[oó]n de belleza|belleza/],
    ['barbería', /barber/],
    ['clínica', /cl[ií]nica|doctor|m[eé]dico|consultorio/],
    ['psicología', /psic[oó]log/],
    ['veterinaria', /veterin/],
    ['tienda de ropa', /ropa|prendas|boutique|tienda/],
    ['ecommerce', /ecommerce|tienda online|venta online/],
  ];
  return checks.find(([, re]) => re.test(msg))?.[0] || null;
}

function inferPainPoint(msg) {
  if (/respon(d|s).*mensaje|contestar.*mensaje|atiend/.test(msg)) return 'quiere responder mensajes de clientes más rápido';
  if (/precio|horario|consulta/.test(msg)) return 'recibe consultas repetitivas por WhatsApp';
  if (/turno|agenda|reserva/.test(msg)) return 'quiere organizar turnos o reservas';
  if (/no perder|pierdo|perder clientes|seguimiento/.test(msg)) return 'quiere evitar perder clientes y mejorar seguimiento';
  if (/crm|organizar|ordenar/.test(msg)) return 'quiere organizar consultas y leads';
  return null;
}

const intent = normalizeIntent(parsed.intent);
const meetingLike = intent === 'wants_meeting' || intent === 'wants_demo' || intent === 'wants_callback' || /reuni[oó]n|demo|llamada|llamame|agendar|agenda/.test(message);
const businessType = clean(parsed.business_type) || inferBusinessType(message);
const painPoint = clean(parsed.pain_point) || inferPainPoint(message);
const leadStage = clean(parsed.lead_stage) || (meetingLike ? 'meeting_requested' : intent === 'interested' ? 'interested' : 'new');
const buyingIntent = clean(parsed.buying_intent) || (meetingLike ? 'high' : intent === 'interested' || intent === 'wants_price' ? 'medium' : null);

return [{
  json: {
    ...original,
    classification: parsed,
    intent,
    lead_status: parsed.lead_status || leadStage,
    should_reply: parsed.should_reply !== false,
    should_update_crm: parsed.should_update_crm !== false,
    should_handoff: parsed.should_handoff === true || meetingLike || intent === 'wants_human',
    handoff_reason: parsed.handoff_reason || (meetingLike ? 'User requested a meeting, demo, or callback.' : ''),
    should_create_calendar_event: parsed.should_create_calendar_event === true,
    calendar_event_type: parsed.calendar_event_type || 'none',
    requested_datetime_iso: parsed.requested_datetime_iso || null,
    requested_datetime_end_iso: parsed.requested_datetime_end_iso || null,
    alternate_phone: parsed.alternate_phone || null,
    recommended_action: parsed.recommended_action || '',
    is_spam: parsed.is_spam === true || intent === 'spam',
    confidence: Number(parsed.confidence || 0),
    next_question: parsed.next_question || null,
    summary: parsed.summary || original.combined_text,
    business_type: businessType,
    pain_point: painPoint,
    lead_stage: leadStage,
    buying_intent: buyingIntent,
  },
}];

