const lead = $('Parse Classification').item.json;
const query = $input.first().json || {};
const existing = Array.isArray(query.results) && query.results.length > 0 ? query.results[0] : null;
const props = existing?.properties || {};

function rich(name) {
  const prop = props[name];
  if (!prop) return '';
  const parts = prop.rich_text || prop.title || [];
  return parts.map(part => part.plain_text || part.text?.content || '').join('').trim();
}
function title(name) {
  return (props[name]?.title || []).map(part => part.plain_text || part.text?.content || '').join('').trim();
}
function select(name) { return props[name]?.select?.name || ''; }
function phone(name) { return props[name]?.phone_number || ''; }
function date(name) { return props[name]?.date?.start || ''; }
function checkbox(name) { return props[name]?.checkbox === true; }
function number(name) { return typeof props[name]?.number === 'number' ? props[name].number : 0; }

const memory = {
  phone: title('Phone') || lead.phone || '',
  name: rich('Name') || lead.push_name || '',
  text_phone: phone('Text') || lead.phone || '',
  status: select('Status') || lead.lead_status || 'new',
  intent: select('Intent') || lead.intent || 'unknown',
  business_type: rich('Business Type'),
  pain_point: rich('Pain Point'),
  conversation_summary: rich('Conversation Summary') || rich('Summary'),
  last_user_message: rich('Last User Message') || rich('Last Message'),
  last_bot_reply: rich('Last Bot Reply'),
  lead_stage: select('Lead Stage'),
  buying_intent: select('Buying Intent'),
  repetition_risk: checkbox('Repetition Risk'),
  human_takeover: checkbox('Human Takeover'),
  messages_count: number('Messages Count'),
  last_contact_at: date('Last Contact At'),
};

return [{
  json: {
    ...lead,
    notion_exists: Boolean(existing),
    notion_page_id: existing?.id || '',
    notion_page_url: existing?.url || '',
    notion_memory: memory,
    business_type: lead.business_type || memory.business_type || null,
    pain_point: lead.pain_point || memory.pain_point || null,
    lead_stage: lead.lead_stage || memory.lead_stage || lead.lead_status || 'new',
    buying_intent: lead.buying_intent || memory.buying_intent || null,
    previous_conversation_summary: memory.conversation_summary || '',
    previous_last_user_message: memory.last_user_message || '',
    previous_last_bot_reply: memory.last_bot_reply || '',
    messages_count: memory.messages_count || 0,
    human_takeover: memory.human_takeover === true,
  },
}];

