const context = $('Build Lead Memory From Notion').item.json;
const notion = $input.first().json || {};
const pageId = notion.id || context.notion_page_id || '';
const pageUrl = notion.url || context.notion_page_url || '';
return [{
  json: {
    ...context,
    notion_saved: Boolean(pageId) && !notion.error,
    notion_operation: context.notion_exists ? 'updated_existing_lead' : 'created_new_lead',
    notion_page_id: pageId,
    notion_page_url: pageUrl,
    notion_error: notion.error?.message || notion.message || '',
  },
}];

const input = $input.first().json || {};
return [{
  json: {
    ...input,
    telegram_handoff_sent: false,
    telegram_message_id: '',
  },
}];

const context = $('Merge Notion Result').item.json;
const telegram = $input.first().json || {};
return [{
  json: {
    ...context,
    telegram_handoff_sent: !telegram.error,
    telegram_message_id: telegram.message_id || telegram.result?.message_id || '',
    telegram_error: telegram.error?.message || '',
  },
}];

const input = $input.first().json || {};
const memory = input.notion_memory || {};
const businessType = input.business_type || memory.business_type || null;
const painPoint = input.pain_point || memory.pain_point || null;
const leadStage = input.lead_stage || memory.lead_stage || input.lead_status || 'new';
const buyingIntent = input.buying_intent || memory.buying_intent || null;
const lastBotReply = memory.last_bot_reply || input.previous_last_bot_reply || '';
const lastUserMessage = memory.last_user_message || input.previous_last_user_message || '';
const conversationSummary = memory.conversation_summary || input.previous_conversation_summary || '';
const messagesCount = Number(memory.messages_count || input.messages_count || 0);

const aiContext = {
  current_message: input.combined_text || '',
  lead: {
    phone: input.phone || '',
    name: input.push_name || memory.name || '',
    business_type: businessType,
    pain_point: painPoint,
    status: input.lead_status || memory.status || 'new',
    intent: input.intent || memory.intent || 'unknown',
    lead_stage: leadStage,
    buying_intent: buyingIntent,
  },
  memory: {
    conversation_summary: conversationSummary,
    last_user_message: lastUserMessage,
    last_bot_reply: lastBotReply,
    messages_count: messagesCount,
  },
  workflow_decision: {
    should_handoff: input.should_handoff === true,
    handoff_reason: input.handoff_reason || null,
    should_create_calendar_event: input.should_create_calendar_event === true,
    calendar_event_type: input.calendar_event_type || 'none',
    requested_datetime_iso: input.requested_datetime_iso || null,
    requested_datetime_end_iso: input.requested_datetime_end_iso || null,
    notion_saved: input.notion_saved === true,
    telegram_handoff_sent: input.telegram_handoff_sent === true,
  },
  conversation_behavior_rules: {
    do_not_greet_repeatedly: true,
    use_name_only_occasionally: true,
    do_not_repeat_questions: true,
    continue_from_last_bot_reply: true,
    ask_one_question_at_a_time: true,
    never_ask_business_type_if_known: Boolean(businessType),
    never_ask_pain_point_if_known: Boolean(painPoint),
  },
};

return [{
  json: {
    ...input,
    business_type: businessType,
    pain_point: painPoint,
    lead_stage: leadStage,
    buying_intent: buyingIntent,
    previous_conversation_summary: conversationSummary,
    previous_last_user_message: lastUserMessage,
    previous_last_bot_reply: lastBotReply,
    messages_count: messagesCount,
    ai_context: aiContext,
  },
}];

const input = $input.first().json || {};
let reply = String(input.reply_text || '').trim();
const lastBot = String(input.previous_last_bot_reply || input.ai_context?.memory?.last_bot_reply || '').trim();
const current = String(input.combined_text || '').trim();
const businessType = String(input.business_type || input.ai_context?.lead?.business_type || '').trim();
const painPoint = String(input.pain_point || input.ai_context?.lead?.pain_point || '').trim();

function normalize(text) {
  return String(text || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9ñ\s]/g, ' ').replace(/\s+/g, ' ').trim();
}
function similarity(a, b) {
  const aw = new Set(normalize(a).split(' ').filter(Boolean));
  const bw = new Set(normalize(b).split(' ').filter(Boolean));
  if (!aw.size || !bw.size) return 0;
  return [...aw].filter(word => bw.has(word)).length / Math.max(aw.size, bw.size);
}
function startsWithGreeting(text) { return /^(hola|buenas|qué tal|que tal|hola\s+[a-záéíóúñ]+)/i.test(String(text || '').trim()); }
function removeOpeningGreeting(text) { return String(text || '').replace(/^(hola|buenas|qué tal|que tal)(\s+[A-Za-zÁÉÍÓÚáéíóúÑñ]+)?[!,\.\s]*/i, '').trim(); }
function asksBusinessType(text) { return /qué tipo de negocio|que tipo de negocio|a qué se dedica|a que se dedica/i.test(text); }
function asksPainPoint(text) { return /qué consultas|que consultas|qué mensajes|que mensajes|qué problema|que problema|qué necesitás automatizar|que necesitas automatizar/i.test(text); }
function fallbackForwardQuestion() {
  if (businessType && painPoint) return `Perfecto. Con eso ya se puede armar una demo bastante enfocada para ${businessType}. ¿Querés que Nicolás te muestre cómo quedaría el flujo de respuestas por WhatsApp?`;
  if (businessType) return `Perfecto, para ${businessType} suele servir mucho para responder consultas repetidas y ordenar interesados. ¿Querés que te muestre una demo pensada para ese tipo de negocio?`;
  return 'Perfecto, te entiendo. La idea es ayudarte a responder más rápido por WhatsApp y no perder consultas importantes. ¿Querés que Nicolás te muestre una demo corta?';
}

let repetitionRisk = false;
let adjusted = false;

if (lastBot && startsWithGreeting(lastBot) && startsWithGreeting(reply)) {
  reply = removeOpeningGreeting(reply);
  adjusted = true;
}
if (businessType && asksBusinessType(reply)) {
  reply = fallbackForwardQuestion();
  repetitionRisk = true;
  adjusted = true;
}
if (painPoint && asksPainPoint(reply) && similarity(reply, lastBot) > 0.35) {
  reply = fallbackForwardQuestion();
  repetitionRisk = true;
  adjusted = true;
}
if (lastBot && similarity(reply, lastBot) > 0.72) {
  reply = fallbackForwardQuestion();
  repetitionRisk = true;
  adjusted = true;
}
if (!reply) reply = 'Gracias por escribirme. Nicolás va a revisar tu mensaje y te responde en breve.';

function compactSummary() {
  const pieces = [];
  const previous = String(input.previous_conversation_summary || '').trim();
  if (previous) pieces.push(previous);
  if (businessType && !normalize(previous).includes(normalize(businessType))) pieces.push(`El negocio es ${businessType}.`);
  if (painPoint && !normalize(previous).includes(normalize(painPoint))) pieces.push(`Necesidad: ${painPoint}.`);
  if (current) pieces.push(`Último mensaje del lead: ${current}`);
  if (reply) pieces.push(`Última respuesta del bot: ${reply}`);
  return pieces.join(' ').replace(/\s+/g, ' ').slice(-1800);
}

return [{
  json: {
    ...input,
    reply_text: reply,
    repetition_risk: repetitionRisk,
    reply_was_adjusted: adjusted,
    updated_conversation_summary: compactSummary(),
    messages_count: Number(input.messages_count || 0) + 1,
  },
}];

