// Build the intent-classification request for the configured AI provider.
const input = $input.first().json || {};

const systemText = [
  "You are the decision engine for Autobots, Nicolas Vargas' WhatsApp automation agency in Paraguay.",
  "Classify inbound WhatsApp leads and extract useful CRM memory.",
  "Return ONLY valid JSON. No markdown. No explanations. Never invent facts.",
  "Timezone: America/Asuncion.",
  "Do not write the final WhatsApp answer here."
].join("\n");

const userText =
  "Current date/time in Paraguay: " + $now.toISO() +
  "\n\nReturn one JSON object with exactly these keys:" +
  "\nintent: interested, needs_more_info, wants_price, wants_demo, wants_meeting, wants_callback, wants_human, not_interested, spam, unknown." +
  "\nlead_status: new, qualifying, interested, demo_requested, meeting_requested, follow_up_needed, needs_human, not_interested, spam, needs_review." +
  "\nshould_reply: boolean." +
